    <article class="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm"><h2 class="font-semibold">Niveles</h2><form method="post" action="index.php?url=academico_guardar" class="mt-4 flex gap-3"><?= campoCsrf() ?><input type="hidden" name="entidad" value="nivel"><input required name="nombre" placeholder="Primaria" class="form-input mt-0"><input required type="number" min="1" name="orden" placeholder="Orden" class="form-input mt-0 w-24"><button class="rounded-xl bg-blue-600 px-4 text-sm font-semibold text-white">Agregar</button></form><div class="mt-4 space-y-2"><?php foreach ($niveles as $item): ?><div class="flex items-center gap-2 rounded-xl bg-slate-50 px-3 py-2 text-sm"><span class="min-w-0 flex-1"><?= htmlspecialchars($item['orden'] . '. ' . $item['nombre']) ?></span><span class="rounded-full px-2 py-1 text-xs font-semibold <?= $item['estado'] === 'ACTIVO' ? 'bg-emerald-100 text-emerald-700' : 'bg-slate-200 text-slate-600' ?>"><?= $item['estado'] ?></span><button type="button" class="btn-editar" title="Editar nivel" data-entidad="nivel" data-id="<?= $item['id_nivel'] ?>" data-nombre="<?= htmlspecialchars($item['nombre'], ENT_QUOTES) ?>" data-orden="<?= $item['orden'] ?>" onclick="editarAcademico(this)"><i class="bi bi-pencil-square"></i></button><?php $estado = $item['estado'] === 'ACTIVO' ? 'INACTIVO' : 'ACTIVO'; ?><form method="post" action="index.php?url=academico_cambiar_estado" class="inline-flex"><?= campoCsrf() ?><input type="hidden" name="entidad" value="nivel"><input type="hidden" name="id" value="<?= $item['id_nivel'] ?>"><input type="hidden" name="estado" value="<?= $estado ?>"><button class="btn-estado <?= $estado === 'ACTIVO' ? 'btn-activar' : 'btn-desactivar' ?>" title="<?= $estado === 'ACTIVO' ? 'Activar nivel' : 'Desactivar nivel' ?>"><i class="bi <?= $estado === 'ACTIVO' ? 'bi-check-lg' : 'bi-x-lg' ?>"></i></button></form></div><?php endforeach; ?></div></article>

    <article class="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm"><h2 class="font-semibold">Grados</h2><form method="post" action="index.php?url=academico_guardar" class="mt-4 grid gap-3 sm:grid-cols-3"><?= campoCsrf() ?><input type="hidden" name="entidad" value="grado"><select required name="id_nivel" class="form-input mt-0"><option value="">Nivel</option><?php foreach ($niveles as $nivel): ?><option value="<?= $nivel['id_nivel'] ?>"><?= htmlspecialchars($nivel['nombre']) ?></option><?php endforeach; ?></select><input required name="nombre" placeholder="1.º grado" class="form-input mt-0"><div class="flex gap-2"><input required type="number" min="1" name="orden" placeholder="#" class="form-input mt-0"><button class="rounded-xl bg-blue-600 px-3 text-sm font-semibold text-white">Agregar</button></div></form><div class="mt-4 space-y-2"><?php foreach ($grados as $item): ?><div class="flex items-center gap-2 rounded-xl bg-slate-50 px-3 py-2 text-sm"><span class="min-w-0 flex-1"><?= htmlspecialchars($item['nivel'] . ' · ' . $item['nombre']) ?></span><span class="rounded-full px-2 py-1 text-xs font-semibold <?= $item['estado'] === 'ACTIVO' ? 'bg-emerald-100 text-emerald-700' : 'bg-slate-200 text-slate-600' ?>"><?= $item['estado'] ?></span><button type="button" class="btn-editar" title="Editar grado" data-entidad="grado" data-id="<?= $item['id_grado'] ?>" data-nombre="<?= htmlspecialchars($item['nombre'], ENT_QUOTES) ?>" data-orden="<?= $item['orden'] ?>" data-nivel="<?= $item['id_nivel'] ?>" onclick="editarAcademico(this)"><i class="bi bi-pencil-square"></i></button><?php $estado = $item['estado'] === 'ACTIVO' ? 'INACTIVO' : 'ACTIVO'; ?><form method="post" action="index.php?url=academico_cambiar_estado" class="inline-flex"><?= campoCsrf() ?><input type="hidden" name="entidad" value="grado"><input type="hidden" name="id" value="<?= $item['id_grado'] ?>"><input type="hidden" name="estado" value="<?= $estado ?>"><button class="btn-estado <?= $estado === 'ACTIVO' ? 'btn-activar' : 'btn-desactivar' ?>" title="<?= $estado === 'ACTIVO' ? 'Activar grado' : 'Desactivar grado' ?>"><i class="bi <?= $estado === 'ACTIVO' ? 'bi-check-lg' : 'bi-x-lg' ?>"></i></button></form></div><?php endforeach; ?></div></article>

    <article class="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm"><h2 class="font-semibold">Secciones y cupos</h2><form method="post" action="index.php?url=academico_guardar" class="mt-4 grid gap-3 sm:grid-cols-3"><?= campoCsrf() ?><input type="hidden" name="entidad" value="seccion"><select required name="id_grado" class="form-input mt-0"><option value="">Grado</option><?php foreach ($grados as $grado): ?><option value="<?= $grado['id_grado'] ?>"><?= htmlspecialchars($grado['nivel'] . ' · ' . $grado['nombre']) ?></option><?php endforeach; ?></select><input required name="nombre" placeholder="A" class="form-input mt-0"><div class="flex gap-2"><input type="number" min="1" name="capacidad" placeholder="Cap." class="form-input mt-0"><button class="rounded-xl bg-blue-600 px-3 text-sm font-semibold text-white">Agregar</button></div></form><div class="mt-4 space-y-2"><?php foreach ($secciones as $item): ?><?php $llena = $item['capacidad'] !== null && $item['matriculados'] >= $item['capacidad']; ?><div class="flex items-center gap-2 rounded-xl bg-slate-50 px-3 py-2 text-sm"><div class="min-w-0 flex-1"><strong><?= htmlspecialchars($item['nivel'] . ' · ' . $item['grado'] . ' ' . $item['nombre']) ?></strong><span class="block text-xs <?= $llena ? 'text-red-600' : 'text-slate-500' ?>"><?= $item['capacidad'] === null ? 'Sin límite de cupo' : htmlspecialchars($item['matriculados'] . ' / ' . $item['capacidad'] . ' matriculados') ?></span></div><span class="rounded-full px-2 py-1 text-xs font-semibold <?= $item['estado'] === 'ACTIVO' ? 'bg-emerald-100 text-emerald-700' : 'bg-slate-200 text-slate-600' ?>"><?= $item['estado'] ?></span><button type="button" class="btn-editar" title="Editar sección" data-entidad="seccion" data-id="<?= $item['id_seccion'] ?>" data-nombre="<?= htmlspecialchars($item['nombre'], ENT_QUOTES) ?>" data-grado="<?= $item['id_grado'] ?>" data-capacidad="<?= $item['capacidad'] ?>" onclick="editarAcademico(this)"><i class="bi bi-pencil-square"></i></button><?php $estado = $item['estado'] === 'ACTIVO' ? 'INACTIVO' : 'ACTIVO'; ?><form method="post" action="index.php?url=academico_cambiar_estado" class="inline-flex"><?= campoCsrf() ?><input type="hidden" name="entidad" value="seccion"><input type="hidden" name="id" value="<?= $item['id_seccion'] ?>"><input type="hidden" name="estado" value="<?= $estado ?>"><button class="btn-estado <?= $estado === 'ACTIVO' ? 'btn-activar' : 'btn-desactivar' ?>" title="<?= $estado === 'ACTIVO' ? 'Activar sección' : 'Desactivar sección' ?>"><i class="bi <?= $estado === 'ACTIVO' ? 'bi-check-lg' : 'bi-x-lg' ?>"></i></button></form></div><?php endforeach; ?></div></article>
