<div id="modal-editar-academico" class="fixed inset-0 z-[60] hidden overflow-y-auto bg-slate-900/45 p-4"><div class="modal-persona-contenido rounded-2xl bg-white p-6 shadow-2xl"><h2 class="text-lg font-bold">Editar registro académico</h2><form method="post" action="index.php?url=academico_actualizar" class="mt-5 grid gap-4 sm:grid-cols-2"><?= campoCsrf() ?><input id="ea-entidad" type="hidden" name="entidad"><input id="ea-id" type="hidden" name="id"><div data-formulario="periodo" class="contents"><label class="form-label sm:col-span-2">Nombre<input id="ea-periodo-nombre" name="nombre" class="form-input"></label><label class="form-label">Inicio<input id="ea-inicio" type="date" name="fecha_inicio" class="form-input"></label><label class="form-label">Fin<input id="ea-fin" type="date" name="fecha_fin" class="form-input"></label><label class="form-label">Estado<select id="ea-periodo-estado" name="estado" class="form-input"><option>PLANIFICADO</option><option>ACTIVO</option><option>CERRADO</option></select></label></div><div data-formulario="nivel" class="contents"><label class="form-label">Nombre<input id="ea-nivel-nombre" name="nombre" class="form-input"></label><label class="form-label">Orden<input id="ea-nivel-orden" type="number" min="1" name="orden" class="form-input"></label></div><div data-formulario="grado" class="contents"><label class="form-label">Nivel<select id="ea-grado-nivel" name="id_nivel" class="form-input"><?php foreach ($niveles as $nivel): ?><option value="<?= $nivel['id_nivel'] ?>"><?= htmlspecialchars($nivel['nombre']) ?></option><?php endforeach; ?></select></label><label class="form-label">Nombre<input id="ea-grado-nombre" name="nombre" class="form-input"></label><label class="form-label">Orden<input id="ea-grado-orden" type="number" min="1" name="orden" class="form-input"></label></div><div data-formulario="seccion" class="contents"><label class="form-label">Grado<select id="ea-seccion-grado" name="id_grado" class="form-input"><?php foreach ($grados as $grado): ?><option value="<?= $grado['id_grado'] ?>"><?= htmlspecialchars($grado['nivel'] . ' · ' . $grado['nombre']) ?></option><?php endforeach; ?></select></label><label class="form-label">Sección<input id="ea-seccion-nombre" name="nombre" class="form-input"></label><label class="form-label">Capacidad <span class="font-normal text-slate-400">(vacío = sin límite)</span><input id="ea-seccion-capacidad" type="number" min="1" name="capacidad" class="form-input"></label></div></form></div></div>
<script>
function editarAcademico(boton) {
    const entidad = boton.dataset.entidad;
    document.getElementById('ea-entidad').value = entidad;
    document.getElementById('ea-id').value = boton.dataset.id;
    document.querySelectorAll('[data-formulario]').forEach(bloque => { const activo = bloque.dataset.formulario === entidad; bloque.classList.toggle('hidden', !activo); bloque.querySelectorAll('input,select').forEach(campo => campo.disabled = !activo); });
    if (entidad === 'periodo') { document.getElementById('ea-periodo-nombre').value = boton.dataset.nombre; document.getElementById('ea-inicio').value = boton.dataset.inicio; document.getElementById('ea-fin').value = boton.dataset.fin; document.getElementById('ea-periodo-estado').value = boton.dataset.estado; }
    if (entidad === 'nivel') { document.getElementById('ea-nivel-nombre').value = boton.dataset.nombre; document.getElementById('ea-nivel-orden').value = boton.dataset.orden; }
    if (entidad === 'grado') { document.getElementById('ea-grado-nivel').value = boton.dataset.nivel; document.getElementById('ea-grado-nombre').value = boton.dataset.nombre; document.getElementById('ea-grado-orden').value = boton.dataset.orden; }
    if (entidad === 'seccion') { document.getElementById('ea-seccion-grado').value = boton.dataset.grado; document.getElementById('ea-seccion-nombre').value = boton.dataset.nombre; document.getElementById('ea-seccion-capacidad').value = boton.dataset.capacidad; }
    document.getElementById('modal-editar-academico').classList.remove('hidden');
}
</script>
